<script setup lang="ts">const state=reactive({name:'',email:'',subject:'Demande d’information',message:''});const sent=ref(false);const subjects=['Demande d’information','Coordination provinciale','Presse et médias','Autre demande'];useSeoMeta({title:'Contact | Force du Progrès'})</script>
<template><div><PageHero title="Entrer en contact" description="Pour une demande d’information ou une question relative au portail, utilisez le formulaire."/><section class="content-section"><UContainer><DemoNotice class="mb-8"/><div class="contact-grid"><div><div class="section-eyebrow">COORDINATION NATIONALE</div><h2 class="contact-title">Restons en contact.</h2><p class="muted">Adresse, téléphone et courriel officiels seront ajoutés après confirmation.</p><div class="contact-detail"><UIcon name="i-lucide-map-pin"/><div><b>Adresse</b><small>Kinshasa, RDC · à confirmer</small></div></div><div class="contact-detail"><UIcon name="i-lucide-mail"/><div><b>Courriel</b><small>Adresse officielle à communiquer</small></div></div><div class="contact-detail"><UIcon name="i-lucide-share-2"/><div><b>Réseaux sociaux</b><small>Liens à valider par l’équipe de communication</small></div></div></div><UCard><div v-if="sent" class="form-success"><UIcon name="i-lucide-check-circle"/><h3>Simulation terminée</h3><p>Aucun message n’a été transmis : aucun service d’envoi n’est connecté.</p><UButton color="neutral" variant="outline" @click="sent=false">Revenir au formulaire</UButton></div><form v-else class="contact-form" @submit.prevent="sent=true"><h3>Envoyer un message</h3><UFormField label="Nom complet" required><UInput v-model="state.name" placeholder="Votre nom" icon="i-lucide-user" size="xl" class="w-full" required/></UFormField><UFormField label="Adresse e-mail" required><UInput v-model="state.email" type="email" placeholder="vous@exemple.com" icon="i-lucide-mail" size="xl" class="w-full" required/></UFormField><UFormField label="Objet"><USelect v-model="state.subject" :items="subjects" size="xl" class="w-full"/></UFormField><UFormField label="Message" required><UTextarea v-model="state.message" :rows="5" placeholder="Votre message..." class="w-full" required/></UFormField><UButton type="submit" block size="xl">Envoyer (démo)</UButton><small class="form-disclaimer">Aucun renseignement n’est envoyé ou stocké.</small></form></UCard></div></UContainer></section></div></template>